(* [comment removed for export] *)
Local Ltac cc_now SH AC ACC MU1 WM1 WH SB1 SB4 SB2 CEIL AF1 om :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of SH with SHAD _ ?vb (cc_shadow ?len _) =>
    assert (SHc : SHAD mc vb (cc_shadow len (om - vb)))
      by (eapply SHAD_transport; [exact SH| exact MU1| exact WM1| cbn [disjoint_from fst snd]; rewrite cc_shadow_length' by lia; clear - SB1 SB4 SB2 CEIL AF1; lia]) end;
    assert (ACc : ACONST mc)
      by (eapply ACONST_frame; [exact AC| exact MU1| exact WM1| apply Forall_cons; [apply aconst_ok_hi; cbn [fst snd]; unfold AHI_LO; clear - CEIL AF1; lia| apply Forall_nil]]);
